"""Approval-liveness triggers and the worker mark fence on the database clock (F-A, F-5; additive).

Revision series: 0050 to 0054 are committed on this branch and are not edited.

- webdesk_users_guard (migration 0018) compares the expiry of an approved contact approval with
  ``clock_timestamp()`` in its three approval predicates (activation, activation token check, contact change).
  Migration 0053 did not inventory trigger functions, so this was left at transaction-start ``now()``.
- webdesk_role_guard compares the expiry of an administrator appointment (a user_contact_approvals row) with
  ``clock_timestamp()``. Same reason.
- fn_worker_mark_inputs_changed(run) was callable by any worker login for any run, with no lease check. It is
  re-issued as fn_worker_mark_inputs_changed(job, owner): it marks the run stale only when the caller holds the
  job's unexpired lease. It takes the job's KEY SHARE lock first (job before run), as the step fence does.
  It returns false, and changes nothing, when the caller does not hold the lease.

Token consumption (``consumed_at = now()``) is intentionally unchanged: it compares within one transaction.
Session, proof, token-lifetime and read-grant expiry are out of the approval-liveness ruling and are unchanged.
Downgrade restores the exact prior definitions captured from the database before this revision.
"""

from __future__ import annotations

from collections.abc import Sequence

from alembic import op

revision: str = "0055_approval_worker_fence"
down_revision: str | None = "0054_contact_change_reject_clock"
branch_labels: str | Sequence[str] | None = None
depends_on: str | Sequence[str] | None = None


UPGRADE_SQL = "CREATE OR REPLACE FUNCTION public.webdesk_users_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nBEGIN\n    IF NEW.contact_revision IS DISTINCT FROM OLD.contact_revision\n       AND current_user <> 'webdesk_guard_owner' THEN\n        RAISE EXCEPTION 'contact revision changes only through the contact owner function'\n            USING ERRCODE = 'insufficient_privilege';\n    END IF;\n\n    IF NEW.identity_subject IS DISTINCT FROM OLD.identity_subject\n       OR NEW.created_by_user_id IS DISTINCT FROM OLD.created_by_user_id\n       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN\n        RAISE EXCEPTION 'identity fields are immutable'\n            USING ERRCODE = 'insufficient_privilege';\n    END IF;\n\n    IF NEW.session_epoch < OLD.session_epoch THEN\n        RAISE EXCEPTION 'session epoch never decreases'\n            USING ERRCODE = 'check_violation';\n    END IF;\n\n    IF NEW.status IS DISTINCT FROM OLD.status THEN\n        IF OLD.status = 'pending_contact_approval' AND NEW.status = 'pending_activation' THEN\n            IF NOT EXISTS (\n                SELECT 1 FROM user_contact_approvals a\n                WHERE a.user_id = NEW.user_id AND a.status = 'approved'\n                  AND a.requested_email_normalized = NEW.normalized_email\n                  AND a.expires_at > clock_timestamp()\n            ) THEN\n                RAISE EXCEPTION 'activation requires an approved, unexpired contact approval'\n                    USING ERRCODE = 'check_violation';\n            END IF;\n        ELSIF OLD.status = 'pending_contact_approval' AND NEW.status = 'disabled' THEN\n            IF NOT EXISTS (\n                SELECT 1 FROM user_withdrawals w\n                WHERE w.user_id = NEW.user_id AND w.tx_id = pg_current_xact_id()\n            ) OR EXISTS (\n                SELECT 1 FROM user_contact_approvals a\n                WHERE a.user_id = NEW.user_id AND a.status = 'approved'\n            ) THEN\n                RAISE EXCEPTION 'disabling a pending account requires an eligible withdrawal'\n                    USING ERRCODE = 'check_violation';\n            END IF;\n        ELSIF OLD.status = 'pending_activation' AND NEW.status = 'active' THEN\n            IF NOT EXISTS (\n                SELECT 1 FROM account_activation_tokens t\n                WHERE t.user_id = NEW.user_id AND t.purpose = 'activate'\n                  AND t.consumed_at = now()\n            ) OR NOT EXISTS (\n                SELECT 1 FROM user_contact_approvals a\n                WHERE a.user_id = NEW.user_id AND a.status = 'approved'\n                  AND a.requested_email_normalized = NEW.normalized_email\n                  AND a.expires_at > clock_timestamp()\n            ) THEN\n                RAISE EXCEPTION 'activation requires a token consumed in this transaction and a live approval'\n                    USING ERRCODE = 'check_violation';\n            END IF;\n        ELSIF OLD.status = 'active' AND NEW.status = 'disabled'\n              AND current_user = 'webdesk_guard_owner' THEN\n            NULL;\n        ELSE\n            RAISE EXCEPTION 'account status transition % to % is not permitted',\n                OLD.status, NEW.status\n                USING ERRCODE = 'check_violation';\n        END IF;\n    END IF;\n\n    IF NEW.normalized_email IS DISTINCT FROM OLD.normalized_email THEN\n        IF NEW.normalized_email IS NULL THEN\n            -- Only an audited withdrawal in this same transaction may clear a contact.\n            IF OLD.status <> 'pending_contact_approval' OR NEW.status <> 'disabled'\n               OR EXISTS (\n                   SELECT 1 FROM user_contact_approvals a\n                   WHERE a.user_id = NEW.user_id AND a.status = 'approved'\n               )\n               OR NOT EXISTS (\n                   SELECT 1 FROM user_withdrawals w\n                   WHERE w.user_id = NEW.user_id AND w.tx_id = pg_current_xact_id()\n               ) THEN\n                RAISE EXCEPTION 'contact release requires an eligible withdrawal'\n                    USING ERRCODE = 'check_violation';\n            END IF;\n        ELSIF NOT EXISTS (\n            SELECT 1 FROM user_contact_approvals a\n            WHERE a.user_id = NEW.user_id AND a.status = 'approved'\n              AND a.requested_email_normalized = NEW.normalized_email\n              AND a.expires_at > clock_timestamp()\n        ) THEN\n            RAISE EXCEPTION 'contact change requires a matching approved contact approval'\n                USING ERRCODE = 'check_violation';\n        END IF;\n    END IF;\n    RETURN NEW;\nEND\n$function$;\nCREATE OR REPLACE FUNCTION public.webdesk_role_guard()\n RETURNS trigger\n LANGUAGE plpgsql\nAS $function$\nDECLARE\n    active_admins integer;\n    target_status text;\n    appt user_contact_approvals%ROWTYPE;\nBEGIN\n    IF NEW.role <> 'Administrator' THEN\n        IF NEW.assigned_by_system IS NOT NULL THEN\n            RAISE EXCEPTION 'only the Administrator role can be system-assigned'\n                USING ERRCODE = 'insufficient_privilege';\n        END IF;\n        IF NOT EXISTS (\n            SELECT 1 FROM role_assignments r JOIN users u ON u.user_id = r.user_id\n            WHERE r.user_id = NEW.assigned_by_user_id AND r.role = 'Administrator'\n              AND r.revoked_at IS NULL AND u.status = 'active'\n        ) THEN\n            RAISE EXCEPTION 'role grants require an active Administrator grantor'\n                USING ERRCODE = 'insufficient_privilege';\n        END IF;\n        IF NOT EXISTS (SELECT 1 FROM users WHERE user_id = NEW.user_id AND status = 'active') THEN\n            RAISE EXCEPTION 'role recipient must be active'\n                USING ERRCODE = 'check_violation';\n        END IF;\n        RETURN NEW;\n    END IF;\n\n    PERFORM pg_advisory_xact_lock(727272);\n    SELECT status INTO target_status FROM users WHERE user_id = NEW.user_id;\n    SELECT count(DISTINCT r.user_id) INTO active_admins\n    FROM role_assignments r JOIN users u ON u.user_id = r.user_id\n    WHERE r.role = 'Administrator' AND r.revoked_at IS NULL AND u.status = 'active';\n\n    IF NEW.assigned_by_system = 'system:bootstrap' THEN\n        IF current_user <> 'webdesk_ceremony' THEN\n            RAISE EXCEPTION 'bootstrap grant requires the ceremony role'\n                USING ERRCODE = 'insufficient_privilege';\n        END IF;\n        IF active_admins <> 0 THEN\n            RAISE EXCEPTION 'bootstrap grant is only permitted with zero active Administrators'\n                USING ERRCODE = 'check_violation';\n        END IF;\n        IF target_status NOT IN ('pending_activation', 'active') THEN\n            RAISE EXCEPTION 'bootstrap target must be a ceremony-approved contact'\n                USING ERRCODE = 'check_violation';\n        END IF;\n        IF NEW.appointment_approval_id IS NULL THEN\n            RAISE EXCEPTION 'bootstrap grant requires its install appointment'\n                USING ERRCODE = 'check_violation';\n        END IF;\n    ELSE\n        IF NOT EXISTS (\n            SELECT 1 FROM role_assignments r JOIN users u ON u.user_id = r.user_id\n            WHERE r.user_id = NEW.assigned_by_user_id AND r.role = 'Administrator'\n              AND r.revoked_at IS NULL AND u.status = 'active'\n        ) THEN\n            RAISE EXCEPTION 'Administrator grants require an active Administrator grantor'\n                USING ERRCODE = 'insufficient_privilege';\n        END IF;\n        IF target_status <> 'active' THEN\n            RAISE EXCEPTION 'Administrator recipient must be active'\n                USING ERRCODE = 'check_violation';\n        END IF;\n        IF active_admins < 2 AND NEW.appointment_approval_id IS NULL THEN\n            RAISE EXCEPTION 'below two active Administrators, a consumable appointment is required'\n                USING ERRCODE = 'check_violation';\n        END IF;\n    END IF;\n\n    IF NEW.appointment_approval_id IS NOT NULL THEN\n        SELECT * INTO appt FROM user_contact_approvals\n        WHERE approval_id = NEW.appointment_approval_id FOR UPDATE;\n        IF NOT FOUND OR appt.user_id <> NEW.user_id OR appt.ceremony_id IS NULL\n           OR NOT appt.administrator_appointment OR appt.status <> 'approved'\n           OR appt.expires_at <= clock_timestamp() OR appt.appointment_consumed_at IS NOT NULL THEN\n            RAISE EXCEPTION 'appointment is invalid, expired or already consumed'\n                USING ERRCODE = 'check_violation';\n        END IF;\n        PERFORM webdesk_guard.fn_consume_appointment(NEW.appointment_approval_id, NEW.assignment_id);\n    END IF;\n    RETURN NEW;\nEND\n$function$;\nSET ROLE webdesk_guard_owner;\nDROP FUNCTION webdesk_guard.fn_worker_mark_inputs_changed(uuid);\nCREATE FUNCTION webdesk_guard.fn_worker_mark_inputs_changed(p_job uuid, p_owner text)\nRETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public AS $fn$\nDECLARE\n    v_run uuid;\nBEGIN\n    SELECT j.run_id INTO v_run FROM workflow_jobs j\n     WHERE j.job_id = p_job AND j.lease_owner = p_owner AND j.job_status = 'leased'\n       AND j.lease_expires_at > clock_timestamp()\n    FOR KEY SHARE;\n    IF NOT FOUND THEN\n        RETURN false;\n    END IF;\n    UPDATE workflow_runs\n       SET is_stale = true, stale_at = now(), stale_reason = 'inputs_changed_during_run'\n     WHERE run_id = v_run;\n    RETURN true;\nEND\n$fn$;\nREVOKE ALL ON FUNCTION webdesk_guard.fn_worker_mark_inputs_changed(uuid, text) FROM PUBLIC;\nGRANT EXECUTE ON FUNCTION webdesk_guard.fn_worker_mark_inputs_changed(uuid, text) TO webdesk_worker;\nRESET ROLE;\n"

